import { pool } from '../../../packages/database/src/pool.js';

export type ErasureStatus = 'pending' | 'processing' | 'failed' | 'completed';

export interface ErasureRequestRow {
  id: string;
  merchant_id: string;
  customer_id: string;
  status: ErasureStatus;
  attempts: number;
  created_at: Date;
  updated_at: Date;
  completed_at: Date | null;
  last_error: string | null;
}

export class ErasureRepository {
  async createOrResume(
    client: pg.PoolClient,
    merchantId: string,
    customerId: string,
    idempotencyKey: string,
  ): Promise<ErasureRequestRow> {
    await client.query(`SELECT pg_advisory_xact_lock(hashtext($1))`, [`erasure:${merchantId}:${idempotencyKey}`]);
    await client.query(`SELECT pg_advisory_xact_lock(hashtext($1))`, [`erasure:${merchantId}:${customerId}`]);

    const keyed = await client.query<{ customer_id: string; request_id: string }>(
      `SELECT customer_id,request_id FROM operations.customer_erasure_idempotency_keys
       WHERE merchant_id=$1 AND key=$2`,
      [merchantId, idempotencyKey],
    );
    if (keyed.rows[0]?.customer_id !== undefined && keyed.rows[0].customer_id !== customerId) {
      throw Object.assign(new Error('idempotency_key_conflict'), { statusCode: 409 });
    }

    let request = await client.query<ErasureRequestRow>(
      `SELECT * FROM operations.customer_erasure_requests WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    if (!request.rows[0]) {
      const customer = await client.query(
        `SELECT 1 FROM customers.customers WHERE merchant_id=$1 AND id=$2`,
        [merchantId, customerId],
      );
      if (!customer.rowCount) throw Object.assign(new Error('customer_not_found'), { statusCode: 404 });
      request = await client.query<ErasureRequestRow>(
        `INSERT INTO operations.customer_erasure_requests(merchant_id,customer_id)
         VALUES($1,$2) RETURNING *`,
        [merchantId, customerId],
      );
    } else if (request.rows[0].status === 'failed') {
      request = await client.query<ErasureRequestRow>(
        `UPDATE operations.customer_erasure_requests
         SET status='pending',last_error=NULL,updated_at=now()
         WHERE id=$1 RETURNING *`,
        [request.rows[0].id],
      );
    }

    const row = request.rows[0]!;
    await client.query(
      `INSERT INTO operations.customer_erasure_idempotency_keys(merchant_id,key,customer_id,request_id)
       VALUES($1,$2,$3,$4) ON CONFLICT(merchant_id,key) DO NOTHING`,
      [merchantId, idempotencyKey, customerId, row.id],
    );
    return row;
  }

  async find(merchantId: string, requestId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM operations.customer_erasure_requests WHERE merchant_id=$1 AND id=$2`,
      [merchantId, requestId],
    );
    return result.rows[0];
  }

  async claim(workerId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `UPDATE operations.customer_erasure_requests
       SET status='processing',attempts=attempts+1,last_error=NULL,locked_by=$1,locked_at=now(),
           lease_expires_at=now()+interval '2 minutes',updated_at=now()
       WHERE id=(SELECT id FROM operations.customer_erasure_requests
         WHERE status IN ('pending','failed') OR (status='processing' AND lease_expires_at<now())
         ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT 1)
       RETURNING *`,
      [workerId],
    );
    return result.rows[0];
  }

  async complete(requestId: string): Promise<void> {
    await pool.query(
      `UPDATE operations.customer_erasure_requests
       SET status='completed',completed_at=now(),updated_at=now(),last_error=NULL,
           locked_by=NULL,locked_at=NULL,lease_expires_at=NULL WHERE id=$1`,
      [requestId],
    );
  }

  async fail(requestId: string, errorCode: string): Promise<void> {
    await pool.query(
      `UPDATE operations.customer_erasure_requests
       SET status='failed',last_error=$2,updated_at=now(),locked_by=NULL,locked_at=NULL,lease_expires_at=NULL
       WHERE id=$1`,
      [requestId, errorCode],
    );
  }
}

export function serializeErasure(row: ErasureRequestRow): Record<string, unknown> {
  return {
    id: row.id,
    customerId: row.customer_id,
    status: row.status,
    attempts: row.attempts,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
    completedAt: row.completed_at,
    lastError: row.last_error,
  };
}
