import { pool, transaction } from '../../../packages/database/src/pool.js';
import { CUSTOMER_INDEX, searchClient } from '../../../packages/search/src/client.js';
import { DOCUMENT_BUCKET, objectStore } from '../../../packages/storage/src/minio.js';
import { ErasureRepository, type ErasureRequestRow } from './erasure-repository.js';

const ERROR_CODES = {
  CLEANUP_FAILED: 'cleanup_failed',
  WORK_IN_PROGRESS: 'customer_work_in_progress',
} as const;

export class ErasureService {
  constructor(private readonly repository = new ErasureRepository()) {}

  async request(merchantId: string, customerId: string, idempotencyKey: string): Promise<ErasureRequestRow> {
    return await transaction(async (client) =>
      await this.repository.createOrResume(client, merchantId, customerId, idempotencyKey));
  }

  async erase(row: ErasureRequestRow): Promise<void> {
    const personalValues = await this.personalValues(row.merchant_id, row.customer_id);
    const objectKeys = await this.customerObjectKeys(row.merchant_id, row.customer_id);
    await this.scrubImportArtifacts(row.merchant_id, personalValues);
    await this.deleteObjects(objectKeys);
    await this.deleteProjection(row.merchant_id, row.customer_id);
    await transaction(async (client) => await this.eraseDatabase(client, row));
  }

  private async personalValues(merchantId: string, customerId: string): Promise<Set<string>> {
    const result = await pool.query<{ value: unknown }>(
      `SELECT to_jsonb(c) value FROM customers.customers c WHERE merchant_id=$1 AND id=$2
       UNION ALL SELECT to_jsonb(a) FROM customers.addresses a WHERE merchant_id=$1 AND customer_id=$2
       UNION ALL SELECT to_jsonb(c) FROM customers.contacts c WHERE merchant_id=$1 AND customer_id=$2
       UNION ALL SELECT to_jsonb(p) FROM customers.payment_method_refs p WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    const values = new Set<string>();
    const collect = (value: unknown): void => {
      if (typeof value === 'string' && value !== merchantId && value !== customerId) values.add(value);
      else if (Array.isArray(value)) value.forEach(collect);
      else if (value && typeof value === 'object') Object.values(value as Record<string, unknown>).forEach(collect);
    };
    result.rows.forEach((row) => collect(row.value));
    return values;
  }

  private async customerObjectKeys(merchantId: string, customerId: string): Promise<string[]> {
    const result = await pool.query<{ object_key: string }>(
      `SELECT object_key FROM operations.document_manifests
       WHERE merchant_id=$1 AND customer_id=$2 AND document_type IN ('invoice','receipt')`,
      [merchantId, customerId],
    );
    return result.rows.map((row) => row.object_key);
  }

  private async scrubImportArtifacts(merchantId: string, personalValues: Set<string>): Promise<void> {
    if (!personalValues.size) return;
    const imports = await pool.query<{ object_key: string }>(
      `SELECT object_key FROM customers.customer_imports WHERE merchant_id=$1`,
      [merchantId],
    );
    for (const { object_key: objectKey } of imports.rows) {
      try {
        const stream = await objectStore.getObject(DOCUMENT_BUCKET, objectKey);
        const chunks: Buffer[] = [];
        for await (const chunk of stream) chunks.push(Buffer.from(chunk));
        const original = JSON.parse(Buffer.concat(chunks).toString('utf8')) as unknown;
        const scrub = (value: unknown): unknown => {
          if (typeof value === 'string') return personalValues.has(value) ? '[deleted]' : value;
          if (Array.isArray(value)) return value.map(scrub);
          if (value && typeof value === 'object') {
            return Object.fromEntries(Object.entries(value as Record<string, unknown>).map(([key, item]) => [key, scrub(item)]));
          }
          return value;
        };
        const content = JSON.stringify(scrub(original));
        await objectStore.putObject(DOCUMENT_BUCKET, objectKey, content, Buffer.byteLength(content), {
          'Content-Type': 'application/json',
        });
      } catch (error) {
        const code = (error as { code?: string }).code;
        if (code !== 'NoSuchKey' && code !== 'NoSuchObject') throw error;
      }
    }
  }

  private async deleteObjects(objectKeys: string[]): Promise<void> {
    for (const objectKey of objectKeys) {
      await objectStore.removeObject(DOCUMENT_BUCKET, objectKey);
    }
  }

  private async deleteProjection(merchantId: string, customerId: string): Promise<void> {
    try {
      await searchClient.delete({ index: CUSTOMER_INDEX, id: `${merchantId}:${customerId}`, refresh: true });
    } catch (error) {
      if ((error as { statusCode?: number }).statusCode !== 404) throw error;
    }
    const redis = new Redis(config().REDIS_URL);
    try {
      const key = `merchant:${merchantId}:customer:${customerId}`;
      await redis.del(key, `${key}:activity`);
    } finally {
      await redis.quit();
    }
  }

  private async eraseDatabase(client: pg.PoolClient, request: ErasureRequestRow): Promise<void> {
    const { merchant_id: merchantId, customer_id: customerId } = request;
    await client.query(`SELECT pg_advisory_xact_lock(hashtext($1))`, [`customer:${merchantId}:${customerId}`]);
