    await client.query(
      `UPDATE payments.payment_intents
       SET customer_snapshot='{"status":"erased"}'::jsonb,description=NULL,updated_at=now()
       WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId],
    );
    await client.query(
      `UPDATE payments.payment_attempts a SET request_payload='{}'::jsonb,response_payload='{}'::jsonb,failure_message=NULL
       FROM payments.payment_intents p WHERE a.payment_intent_id=p.id AND p.merchant_id=$1 AND p.customer_id=$2`,
      [merchantId, customerId],
