    await client.query(
      `UPDATE payments.disputes d SET evidence='{}'::jsonb
       FROM payments.payment_intents p WHERE d.payment_intent_id=p.id AND p.merchant_id=$1 AND p.customer_id=$2`,
      [merchantId, customerId],
    );
    await client.query(
      `UPDATE payments.invoices SET billing_snapshot='{}'::jsonb,object_key=NULL
       WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId],
    );

    await client.query(
      `DELETE FROM operations.notifications WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId],
    );
    await client.query(
      `DELETE FROM operations.email_deliveries WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId],
    );
    await client.query(
      `DELETE FROM operations.notification_preferences WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId],
    );
    await client.query(
      `DELETE FROM operations.analytics_events WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId],
    );
    await client.query(
      `DELETE FROM operations.document_manifests WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId],
    );
    await client.query(
      `UPDATE operations.jobs SET status='cancelled',payload='{}'::jsonb,locked_by=NULL,locked_at=NULL,lease_expires_at=NULL
       WHERE merchant_id=$1 AND payload->>'customerId'=$2 AND status<>'completed'`, [merchantId, customerId],
    );
    await client.query(
      `UPDATE operations.outbox_events SET payload=jsonb_build_object('customerId',$2::text,'erased',true)
       WHERE merchant_id=$1 AND (payload->>'customerId'=$2::text OR (aggregate_type='customer' AND aggregate_id=$2))`,
      [merchantId, customerId],
    );
    await client.query(
      `UPDATE operations.dead_letters SET payload='{}'::jsonb
       WHERE payload->>'customerId'=$2 AND source_id IN (
         SELECT id::text FROM operations.outbox_events WHERE merchant_id=$1
         UNION SELECT id::text FROM operations.jobs WHERE merchant_id=$1)`,
      [merchantId, customerId],
    );
    await client.query(
      `DELETE FROM platform.audit_logs WHERE merchant_id=$1 AND target_type='customer' AND target_id=$2::text`,
      [merchantId, customerId],
    );

    await client.query(
      `UPDATE customers.support_messages SET author_id=NULL,body='[deleted]',attachments='[]'::jsonb
       WHERE author_type='customer' AND author_id=$2 AND merchant_id=$1`, [merchantId, customerId],
    );
    await client.query(
      `UPDATE customers.support_tickets SET subject='[deleted customer]'
       WHERE merchant_id=$1 AND id IN (SELECT ticket_id FROM customers.support_participants WHERE customer_id=$2)`,
      [merchantId, customerId],
