  }
}

export function startErasureWorker(signal: AbortSignal): void {
  const repository = new ErasureRepository();
  const service = new ErasureService(repository);
  const workerId = `customer-erasure-${randomUUID()}`;
  void (async () => {
    while (!signal.aborted) {
      const request = await repository.claim(workerId);
      if (!request) {
        await new Promise((resolve) => setTimeout(resolve, 250));
        continue;
      }
      try {
        await service.erase(request);
        await repository.complete(request.id);
      } catch (error) {
        const code = (error as { erasureCode?: string }).erasureCode ?? ERROR_CODES.CLEANUP_FAILED;
        await repository.fail(request.id, code);
      }
    }
  })();
}
